body_text:
:root {
  --ck-bg: #f6f8fb;
  --ck-surface: #fff;
  --ck-text: #101828;
  --ck-muted: #667085;
  --ck-line: #e4e7ec;
  --ck-blue: #185abc;
  --ck-blue-dark: #123f88;
  --ck-blue-soft: #eaf1ff;
  --ck-orange: #f26b21;
  --ck-shadow: 0 16px 46px rgba(16, 24, 40, .09);
}
* { box-sizing: border-box; }
body { margin: 0; background: var(--ck-bg); color: var(--ck-text); font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
.ck-wrap { max-width: 1180px; margin: 0 auto; padding-left: 18px; padding-right: 18px; }
.ck-hero { background: linear-gradient(135deg, rgba(255,255,255,.96), rgba(235,242,255,.94)), url("https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&fit=crop&w=1800&q=80"); background-size: cover; background-position: center; border-bottom: 1px solid var(--ck-line); }
.ck-hero-inner { max-width: 1180px; min-height: 560px; margin: 0 auto; padding: 62px 18px 54px; display: grid; grid-template-columns: minmax(0, 1.45fr) minmax(320px, .85fr); gap: 42px; align-items: center; }
.ck-kicker { display: inline-flex; margin-bottom: 16px; padding: 7px 11px; border-radius: 999px; background: var(--ck-blue-soft); color: var(--ck-blue-dark); font-size: 12px; font-weight: 850; }
.ck-title { max-width: 780px; margin: 0; color: var(--ck-text); font-size: clamp(40px, 5.2vw, 68px); line-height: 1.02; font-weight: 920; letter-spacing: 0; }
.ck-title span, .ck-form-title span { color: var(--ck-orange); }
.ck-sub { max-width: 790px; margin: 20px 0 0; color: #475467; font-size: 18px; line-height: 1.72; }
.ck-actions { display: flex; gap: 11px; flex-wrap: wrap; margin-top: 28px; }
.ck-btn { min-height: 47px; display: inline-flex; align-items: center; justify-content: center; padding: 0 18px; border: 1px solid var(--ck-line); border-radius: 8px; background: #fff; color: var(--ck-blue); font-size: 14px; font-weight: 850; text-decoration: none; transition: transform .17s ease, border-color .17s ease, background .17s ease; }
.ck-btn:hover { transform: translateY(-1px); border-color: #b9c9ee; background: var(--ck-blue-soft); }
.ck-btn-primary { border-color: var(--ck-blue); background: var(--ck-blue); color: #fff; box-shadow: 0 10px 24px rgba(24,90,188,.2); }
.ck-btn-primary:hover { background: var(--ck-blue-dark); color: #fff; }
.ck-hero-panel, .ck-tool, .ck-path, .ck-feature, .ck-story, .ck-seo, .ck-final { border: 1px solid var(--ck-line); border-radius: 8px; background: var(--ck-surface); box-shadow: 0 6px 20px rgba(21,32,56,.04); }
.ck-hero-panel { padding: 23px; background: rgba(255,255,255,.94); box-shadow: var(--ck-shadow); }
.ck-form-title { display: block; margin: 0 0 16px; color: var(--ck-text); font-size: clamp(26px, 3.2vw, 38px); line-height: 1.05; font-weight: 920; letter-spacing: 0; }
.ck-panel-list { display: grid; gap: 11px; margin: 18px 0 0; }
.ck-panel-list div { padding: 12px; border-radius: 8px; background: #f8fafc; }
.ck-panel-list strong { display: block; margin-bottom: 4px; font-size: 13px; }
.ck-panel-list span { color: var(--ck-muted); font-size: 12px; line-height: 1.5; }
.ck-live { background: #101828; color: #fff; }
.ck-live-inner { max-width: 1180px; margin: 0 auto; padding: 11px 18px; display: grid; grid-template-columns: repeat(5,minmax(0,1fr)); gap: 8px; }
.ck-live-item { min-width: 0; padding: 4px 10px; border-left: 1px solid rgba(255,255,255,.14); }
.ck-live-item:first-child { border-left: 0; }
.ck-live-label { display: block; margin-bottom: 3px; color: rgba(255,255,255,.62); font-size: 9px; font-weight: 850; letter-spacing: .05em; text-transform: uppercase; }
.ck-live-value { display: block; overflow: hidden; color: #fff; font-size: 12px; font-weight: 850; text-overflow: ellipsis; white-space: nowrap; }
.ck-section { padding-top: 44px; }
.ck-head { display: flex; align-items: end; justify-content: space-between; gap: 18px; margin-bottom: 18px; }
.ck-head h2 { margin: 0; font-size: 28px; line-height: 1.2; letter-spacing: 0; }
.ck-head p { max-width: 760px; margin: 7px 0 0; color: var(--ck-muted); font-size: 14px; line-height: 1.7; }
.ck-tools { display: grid; grid-template-columns: repeat(4,minmax(0,1fr)); gap: 14px; }
.ck-tool { min-height: 190px; padding: 20px; }
.ck-badge { display: inline-flex; margin-bottom: 13px; padding: 5px 8px; border-radius: 999px; background: var(--ck-blue-soft); color: var(--ck-blue-dark); font-size: 10px; font-weight: 850; text-transform: uppercase; }
.ck-tool h3, .ck-path h3, .ck-feature-title, .ck-story strong { margin: 0 0 8px; color: var(--ck-text); }
.ck-tool h3, .ck-path h3 { font-size: 17px; }
.ck-tool p, .ck-path p, .ck-story p { margin: 0 0 14px; color: var(--ck-muted); font-size: 13px; line-height: 1.62; }
.ck-tool small { display: block; margin-bottom: 14px; color: #98a2b3; font-size: 11px; }
.ck-tool a { color: var(--ck-blue); font-size: 13px; font-weight: 850; text-decoration: none; }
.ck-path-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 14px; }
.ck-path { padding: 22px; }
.ck-feature-grid, .ck-stories { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 15px; }
.ck-feature, .ck-story { padding: 20px; }
.ck-feature-title { display: inline-block; margin-bottom: 12px; font-size: 18px; font-weight: 850; text-decoration: none; }
.ck-feature-title:hover { color: var(--ck-blue); }
.ck-stat-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 8px; }
.ck-stat { min-height: 62px; padding: 10px; border-radius: 8px; background: #f8fafc; }
.ck-stat span { display: block; margin-bottom: 4px; color: #98a2b3; font-size: 9px; font-weight: 850; text-transform: uppercase; }
.ck-stat strong { color: var(--ck-text); font-size: 13px; }
.ck-process { display: grid; grid-template-columns: repeat(4,minmax(0,1fr)); gap: 10px; padding: 20px; border: 1px solid var(--ck-line); border-radius: 8px; background: #fff; }
.ck-process-step { padding: 14px; border-radius: 8px; background: #f8fafc; }
.ck-process-step span { display: block; margin-bottom: 8px; color: var(--ck-orange); font-size: 11px; font-weight: 900; }
.ck-process-step strong { display: block; margin-bottom: 5px; font-size: 14px; }
.ck-process-step p { margin: 0; color: var(--ck-muted); font-size: 12px; line-height: 1.55; }
.ck-story-mark { margin-bottom: 10px; color: var(--ck-orange); font-size: 24px; line-height: 1; }
.ck-story strong { display: block; font-size: 12px; }
.ck-community { margin-top: 44px; padding: 30px; border-radius: 8px; background: linear-gradient(135deg, rgba(16,40,92,.96), rgba(24,90,188,.96)), url("https://images.unsplash.com/photo-1517048676732-d65bc937f952?auto=format&fit=crop&w=1400&q=80"); background-size: cover; background-position: center; color: #fff; }
.ck-community h2 { margin: 0 0 8px; color: #fff; font-size: 27px; }
.ck-community > p { max-width: 760px; margin: 0; color: rgba(255,255,255,.82); font-size: 14px; line-height: 1.65; }
.ck-community-grid { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 11px; margin-top: 20px; }
.ck-community-link { display: block; padding: 14px; border: 1px solid rgba(255,255,255,.18); border-radius: 8px; background: rgba(255,255,255,.12); color: #fff; font-size: 13px; font-weight: 850; text-decoration: none; }
.ck-community-link span { display: block; margin-top: 4px; color: rgba(255,255,255,.74); font-size: 11px; font-weight: 650; }
.ck-final { margin-top: 42px; padding: 28px; display: flex; align-items: center; justify-content: space-between; gap: 22px; }
.ck-final h2 { margin: 0 0 6px; font-size: 24px; }
.ck-final p { margin: 0; color: var(--ck-muted); font-size: 14px; }
.ck-seo { margin-top: 42px; margin-bottom: 48px; padding: 28px; }
.ck-seo h2 { margin: 0 0 14px; font-size: 24px; }
.ck-seo h3 { margin: 22px 0 8px; font-size: 18px; }
.ck-seo p { margin: 0 0 12px; color: #475467; font-size: 14px; line-height: 1.8; }
@media (max-width:1000px) { .ck-hero-inner { grid-template-columns: 1fr; } .ck-live-inner { grid-template-columns: repeat(3,minmax(0,1fr)); } .ck-tools, .ck-process { grid-template-columns: repeat(2,minmax(0,1fr)); } .ck-feature-grid, .ck-stories { grid-template-columns: repeat(2,minmax(0,1fr)); } }
@media (max-width:650px) { .ck-hero-inner, .ck-wrap { padding-left: 12px; padding-right: 12px; } .ck-hero-inner { min-height: auto; padding-top: 42px; padding-bottom: 40px; } .ck-title { font-size: 39px; } .ck-sub { font-size: 16px; } .ck-live-inner { grid-template-columns: 1fr 1fr; padding-left: 10px; padding-right: 10px; } .ck-live-item { border-left: 0; border-top: 1px solid rgba(255,255,255,.12); padding: 7px 8px; } .ck-tools, .ck-path-grid, .ck-feature-grid, .ck-process, .ck-stories, .ck-community-grid { grid-template-columns: 1fr; } .ck-section { padding-top: 34px; } .ck-head, .ck-final { align-items: flex-start; flex-direction: column; } }
@media (max-width:650px) {
  .ck-process {
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 4px;
    padding: 8px;
  }
  .ck-process-step {
    min-width: 0;
    padding: 7px 5px;
  }
  .ck-process-step span {
    margin-bottom: 4px;
    font-size: 10px;
  }
  .ck-process-step strong {
    margin-bottom: 4px;
    font-size: 10px;
    line-height: 1.15;
  }
  .ck-process-step p {
    font-size: 9px;
    line-height: 1.25;
  }
  .ck-community {
    padding: 20px 12px;
  }
  .ck-community h2 {
    font-size: 22px;
  }
  .ck-community > p {
    font-size: 12px;
    line-height: 1.5;
  }
  .ck-community-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 5px;
    margin-top: 14px;
  }
  .ck-community-link {
    padding: 8px 5px;
    font-size: 10px;
    line-height: 1.2;
    overflow-wrap: anywhere;
  }
  .ck-community-link span {
    margin-top: 3px;
    font-size: 8px;
    line-height: 1.25;
  }
}
@media (max-width:650px) {
  .ck-live-inner {
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: 3px;
    padding: 8px 6px;
  }
  .ck-live-item {
    padding: 5px 3px;
    border-top: 0;
    border-left: 1px solid rgba(255,255,255,.12);
  }
  .ck-live-item:first-child {
    border-left: 0;
  }
  .ck-live-label {
    font-size: 7px;
    letter-spacing: 0;
  }
  .ck-live-value {
    font-size: 8px;
    white-space: normal;
    line-height: 1.15;
  }
  .ck-tools,
  .ck-path-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 5px;
  }
  .ck-feature-grid,
  .ck-stories,
  .ck-community-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 5px;
  }
  .ck-tool,
  .ck-path,
  .ck-feature,
  .ck-story {
    min-width: 0;
    min-height: 0;
    padding: 8px 5px;
    overflow-wrap: anywhere;
  }
  .ck-badge {
    margin-bottom: 5px;
    padding: 3px 4px;
    font-size: 7px;
    line-height: 1.1;
  }
  .ck-tool h3,
  .ck-path h3,
  .ck-feature-title {
    margin-bottom: 5px;
    font-size: 10px;
    line-height: 1.15;
  }
  .ck-tool p,
  .ck-path p,
  .ck-story p {
    margin-bottom: 7px;
    font-size: 9px;
    line-height: 1.25;
  }
  .ck-tool small,
  .ck-tool a,
  .ck-story strong {
    margin-bottom: 5px;
    font-size: 8px;
    line-height: 1.2;
  }
  .ck-path .ck-btn {
    min-height: 28px;
    padding: 0 5px;
    font-size: 8px;
    line-height: 1.1;
    text-align: center;
  }
  .ck-stat-grid {
    gap: 3px;
  }
  .ck-stat {
    min-height: 34px;
    padding: 4px 3px;
  }
  .ck-stat span {
    margin-bottom: 2px;
    font-size: 6px;
    line-height: 1.1;
  }
  .ck-stat strong {
    font-size: 8px;
    line-height: 1.1;
  }
  .ck-story-mark {
    margin-bottom: 4px;
    font-size: 15px;
  }
}
@media (max-width:650px) {
  .ck-hero-panel {
    padding: 16px 12px;
  }
  .ck-form-title {
    margin-bottom: 10px;
    font-size: 18px;
    line-height: 1.15;
    white-space: nowrap;
  }
}
@media (max-width:650px) {
  .ck-panel-list {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 5px;
  }
  .ck-panel-list div {
    min-width: 0;
    padding: 7px 5px;
    overflow-wrap: anywhere;
  }
  .ck-panel-list strong {
    margin-bottom: 3px;
    font-size: 9px;
    line-height: 1.15;
  }
  .ck-panel-list span {
    font-size: 8px;
    line-height: 1.25;
  }
}
